INSERT INTO rootcause.root_causes (root_cause_id, issue_id, name, slug, description, topics, vendors_applicable)
VALUES (
    'SEC-SQL-RAN-046-RC01', 'SEC-SQL-RAN-046', 'Application secrets / API tokens stored in DB tables',
    'ran-046-application-secrets-api-tokens-stored-in-db-tables', 'API credential theft is the **#2 cause of breaches in 2026**, behind phishing. Modern apps stash OAuth refresh tokens, JWT signing secrets, encryption keys, webhook secrets in regular DB columns. Once read, the attacker pivots straight to the customer''s cloud/payment/messaging accounts — never has to encrypt anything. Detection: column-name pattern scan + read tracking.',
    ARRAY['ransomware', 'ran'], ARRAY['postgresql', 'sqlserver', 'oracle', 'mysql']
) ON CONFLICT (root_cause_id) DO UPDATE SET
    name = EXCLUDED.name, description = EXCLUDED.description,
    topics = EXCLUDED.topics, vendors_applicable = EXCLUDED.vendors_applicable;

