    'ran-047-untrusted-procedural-language-functions', 'PL/PythonU, PL/PerlU, PL/TclU, PL/JavaU, Oracle Java with broad permissions, SQL CLR UNSAFE. Each function = permanent OS shell callable via SQL.',
    ARRAY['ransomware', 'ran'], ARRAY['postgresql', 'sqlserver', 'oracle', 'mysql']
) ON CONFLICT (root_cause_id) DO UPDATE SET
