VALUES (
    'SEC-SQL-RAN-048-RC01', 'SEC-SQL-RAN-048', 'Unpatched critical database CVE',
    'ran-048-unpatched-critical-database-cve', 'version inventory mapped to known-exploited ranges. Current high-priority entries: CVE-2026-2005 (pgcrypto, 20-year heap overflow, CVSS 8.8, ~80% of cloud PostgreSQL affected), CVE-2026-6638 (logical-replication SQL-injection-to-superuser, fixed in PG 18.4 / 17.10 / 16.14 / 15.18 / 14.23), CVE-2026-6476 (pg_createsubscriber, near-9), CVE-2025-8714 (pg_dump code injection), Oracle Jan-2026 CPU cluster, MariaDB CVE-2026-32710, MySQL Jan-2026 CPU (20 patches, 7 remote-no-auth).',
    ARRAY['ransomware', 'ran'], ARRAY['postgresql', 'sqlserver', 'oracle', 'mysql']
) ON CONFLICT (root_cause_id) DO UPDATE SET
    name = EXCLUDED.name, description = EXCLUDED.description,
    topics = EXCLUDED.topics, vendors_applicable = EXCLUDED.vendors_applicable;

