INSERT INTO rootcause.root_causes (root_cause_id, issue_id, name, slug, description, topics, vendors_applicable)
VALUES (
    'SEC-SQL-RAN-054-RC01', 'SEC-SQL-RAN-054', 'Database-to-cloud lateral movement via IMDS',
    'ran-054-database-to-cloud-lateral-movement-via-imds', 'Microsoft Security Blog (Oct 2023) documented SQL Server → cloud lateral via `xp_cmdshell` + `curl 169.254.169.254`. The DB process pulls IAM role credentials from the instance metadata service and pivots into S3 / KMS / Secrets Manager. Detection: network-flow rule on outbound `169.254.169.254` from the DB host.',
    ARRAY['ransomware', 'ran'], ARRAY['postgresql', 'sqlserver', 'oracle', 'mysql']
) ON CONFLICT (root_cause_id) DO UPDATE SET
