INSERT INTO rootcause.root_causes (root_cause_id, issue_id, name, slug, description, topics, vendors_applicable)
VALUES (
    'SEC-SQL-RAN-055-RC01', 'SEC-SQL-RAN-055', 'Cloud control-plane surface flip',
    'ran-055-cloud-control-plane-surface-flip', 'RDS/Aurora flipped to `publicly_accessible`, security group opened to 0.0.0.0/0, parameter group edited to disable SSL or `pgaudit.log`. The single most catastrophic managed-DB attack — never touches SQL. Detection via operator-supplied cloud telemetry diff. AWS GuardDuty RDS Protection documents this surface; Coalition''s 2025 Cyber Claims Report puts cloud-credential misuse at 47% of intrusions.',
    ARRAY['ransomware', 'ran'], ARRAY['postgresql', 'sqlserver', 'oracle', 'mysql']
) ON CONFLICT (root_cause_id) DO UPDATE SET
    name = EXCLUDED.name, description = EXCLUDED.description,
    topics = EXCLUDED.topics, vendors_applicable = EXCLUDED.vendors_applicable;

