VALUES (
    'SEC-SQL-RAN-056-RC01', 'SEC-SQL-RAN-056', 'search_path / schema poisoning',
    'ran-056-search-path-schema-poisoning', 'CVE-2018-1058 family. SECURITY DEFINER function that doesn''t pin its `search_path` gets hijacked by a function the attacker created in a writable schema. Detection: SECURITY DEFINER inventory + public-schema-writability check.',
    ARRAY['ransomware', 'ran'], ARRAY['postgresql', 'sqlserver', 'oracle', 'mysql']
) ON CONFLICT (root_cause_id) DO UPDATE SET
