VALUES (
    'SEC-SQL-RAN-057-RC01', 'SEC-SQL-RAN-057', 'Malicious extension / trojanized library',
    'ran-057-malicious-extension-trojanized-library', 'PG_MEM-family (Aqua Nautilus 2024; 1,500+ servers compromised by April 2025 per The Hacker News). Brute-force → CREATE SUPERUSER → COPY FROM PROGRAM → cryptominer payload. Detection: extension allow-list diff + backdoor-superuser inventory.',
    ARRAY['ransomware', 'ran'], ARRAY['postgresql', 'sqlserver', 'oracle', 'mysql']
) ON CONFLICT (root_cause_id) DO UPDATE SET
    name = EXCLUDED.name, description = EXCLUDED.description,
    topics = EXCLUDED.topics, vendors_applicable = EXCLUDED.vendors_applicable;

INSERT INTO rootcause.root_causes (root_cause_id, issue_id, name, slug, description, topics, vendors_applicable)
VALUES (
    'SEC-SQL-RAN-058-RC01', 'SEC-SQL-RAN-058', 'Out-of-band network exfiltration via DB-internal functions',
    'ran-058-out-of-band-network-exfiltration-via-db-internal-functions', 'Oracle `UTL_HTTP`/`UTL_INADDR` (DNS exfil), PostgreSQL `pgsql-http`/`aws_s3`/`lo_export`, SQL Server `sp_OACreate`+`MSXML2.ServerXMLHTTP` / `xp_smtpsendmail`, MySQL outbound UDFs. The connection originates from the DB process, bypassing all host-network monitoring. UTL_INADDR is the textbook OOB SQL-injection primitive (HackTricks, DBSecWorx).',
    ARRAY['ransomware', 'ran'], ARRAY['postgresql', 'sqlserver', 'oracle', 'mysql']
) ON CONFLICT (root_cause_id) DO UPDATE SET
    name = EXCLUDED.name, description = EXCLUDED.description,
    topics = EXCLUDED.topics, vendors_applicable = EXCLUDED.vendors_applicable;

INSERT INTO rootcause.root_causes (root_cause_id, issue_id, name, slug, description, topics, vendors_applicable)
VALUES (
    'SEC-SQL-RAN-059-RC01', 'SEC-SQL-RAN-059', 'Database configuration tamper',
    'ran-059-database-configuration-tamper', '`ALTER SYSTEM SET ssl=off` / `log_statement=none` / `log_destination=''''` (PostgreSQL); `sp_configure` for `xp_cmdshell`, `Ad Hoc Distributed Queries`, `Ole Automation Procedures` (SQL Server); `audit_trail=NONE` (Oracle). PostgreSQL''s `allow_alter_system` is the only protection and is documented as **not a security mechanism**.',
    ARRAY['ransomware', 'ran'], ARRAY['postgresql', 'sqlserver', 'oracle', 'mysql']
) ON CONFLICT (root_cause_id) DO UPDATE SET
    name = EXCLUDED.name, description = EXCLUDED.description,
    topics = EXCLUDED.topics, vendors_applicable = EXCLUDED.vendors_applicable;

