VALUES (
    'SEC-SQL-RAN-067-RC01', 'SEC-SQL-RAN-067', 'Extended stored procedure / CLR DLL backdoor',
    'ran-067-extended-stored-procedure-clr-dll-backdoor', 'Maggie (DCSO 2022), skip-2.0 (Winnti), and Cobalt-Strike SQL backdoors register themselves as `xp_` procedures or UNSAFE CLR assemblies. Hundreds of MSSQL servers backdoored in the 2022 Maggie campaign alone (BleepingComputer).',
    ARRAY['ransomware', 'ran'], ARRAY['postgresql', 'sqlserver', 'oracle', 'mysql']
) ON CONFLICT (root_cause_id) DO UPDATE SET
    name = EXCLUDED.name, description = EXCLUDED.description,
    topics = EXCLUDED.topics, vendors_applicable = EXCLUDED.vendors_applicable;

INSERT INTO rootcause.root_causes (root_cause_id, issue_id, name, slug, description, topics, vendors_applicable)
VALUES (
    'SEC-SQL-RAN-068-RC01', 'SEC-SQL-RAN-068', 'TDE / encryption-key tampering',
    'ran-068-tde-encryption-key-tampering', 'attacker rotates the TDE master key or drops the certificate, making the database unrecoverable. Microsoft Learn documents that TDE-protected DBs cannot be restored without the original certificate. Detection: certificate state + `pvt_key_last_backup_date`.',
    ARRAY['ransomware', 'ran'], ARRAY['postgresql', 'sqlserver', 'oracle', 'mysql']
) ON CONFLICT (root_cause_id) DO UPDATE SET
    name = EXCLUDED.name, description = EXCLUDED.description,
    topics = EXCLUDED.topics, vendors_applicable = EXCLUDED.vendors_applicable;

INSERT INTO rootcause.root_causes (root_cause_id, issue_id, name, slug, description, topics, vendors_applicable)
VALUES (
    'SEC-SQL-RAN-069-RC01', 'SEC-SQL-RAN-069', 'Honeytoken / canary-row access (proactive)',
    'ran-069-honeytoken-canary-row-access-proactive', 'dbExpert deploys decoy tables with names like `canary_dbexpert_customers` and `canary_dbexpert_credentials` into operator-blessed schemas. Any read of those rows is a confirmed intruder. CrowdStrike, Acalvio, CounterCraft cite this as the highest-signal SQL-layer detection that exists.',
    ARRAY['ransomware', 'ran'], ARRAY['postgresql', 'sqlserver', 'oracle', 'mysql']
) ON CONFLICT (root_cause_id) DO UPDATE SET
    name = EXCLUDED.name, description = EXCLUDED.description,
    topics = EXCLUDED.topics, vendors_applicable = EXCLUDED.vendors_applicable;

INSERT INTO rootcause.root_causes (root_cause_id, issue_id, name, slug, description, topics, vendors_applicable)
VALUES (
    'SEC-SQL-RAN-070-RC01', 'SEC-SQL-RAN-070', 'Anti-forensics — query-history / plan-cache wipe',
    'ran-070-anti-forensics-query-history-plan-cache-wipe', '`DBCC FREEPROCCACHE`, `pg_stat_statements_reset()`, Oracle shared-pool flush, audit-table TRUNCATE. Visibility-suppression immediately before the destructive phase.',
    ARRAY['ransomware', 'ran'], ARRAY['postgresql', 'sqlserver', 'oracle', 'mysql']
) ON CONFLICT (root_cause_id) DO UPDATE SET
    name = EXCLUDED.name, description = EXCLUDED.description,
    topics = EXCLUDED.topics, vendors_applicable = EXCLUDED.vendors_applicable;

INSERT INTO rootcause.root_causes (root_cause_id, issue_id, name, slug, description, topics, vendors_applicable)
VALUES (
    'SEC-SQL-RAN-071-RC01', 'SEC-SQL-RAN-071', 'Geo-velocity / impossible-travel',
    'ran-071-geo-velocity-impossible-travel', 'same login authenticates from two distant geographies within minutes. Catches stolen-credential and session-replay attacks regardless of which tool the attacker uses.',
    ARRAY['ransomware', 'ran'], ARRAY['postgresql', 'sqlserver', 'oracle', 'mysql']
) ON CONFLICT (root_cause_id) DO UPDATE SET
    name = EXCLUDED.name, description = EXCLUDED.description,
    topics = EXCLUDED.topics, vendors_applicable = EXCLUDED.vendors_applicable;

